// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#pragma once#include "Common/GraphicsPipelineStage.h"#include "Common/FullscreenPass.h"#include "Common/PrimitiveRenderPass.h"#include "Common/UtilityPasses.h"#include "DiffractionKernel.h"#include <string>#include <vector>struct SDepthOfFieldParams;class CDepthOfFieldStage : public CGraphicsPipelineStage{public:	static const EGraphicsPipelineStage StageID = eStage_DepthOfField;	CDepthOfFieldStage(CGraphicsPipeline& graphicsPipeline)		: CGraphicsPipelineStage(graphicsPipeline)		, m_passCopySceneTarget(&graphicsPipeline)		, m_passLayerDownscale(&graphicsPipeline)		, m_passGather0(&graphicsPipeline)		, m_passGather1(&graphicsPipeline)		, m_passComposition(&graphicsPipeline)		, m_passSpriteComposition(&graphicsPipeline)		, m_passGhostComposition(&graphicsPipeline)	{		for (auto& pass : m_passTileMinCoC)			pass.SetGraphicsPipeline(&graphicsPipeline);	}	bool IsStageActive(EShaderRenderingFlags flags) const final	{		return CRenderer::CV_r_dof > 0;	}	void Execute();	void Resize(int renderWidth, int renderHeight) override;	//! Adds this frame's lens ghosts into the HDR target. Deliberately NOT part of Execute():	//! a ghost is a second-order internal reflection, so it must not be a light source for the	//! glare family (streaks, anamorphic flare, front filter PSF, halation) - a flare off a	//! ghost would be third order and invisible. The pipeline therefore calls this AFTER the	//! half/quarter resolution downsamples that feed every one of those thresholds, and before	//! the tone map, which is the last reader of the HDR target. Consumes the frame's ghost	//! layer: a second call, or a frame in which the DOF stage did not run, does nothing.	//! See LensGhostSpec.md, "Pipeline placement".	void ExecuteGhostComposite();	//! This frame's lens ghost layer, or null when no ghost was drawn (Amount 0, no source above	//! the threshold, or the DOF stage did not run). Full resolution, RGBA16F, additive.	CTexture* GetGhostLayer() const { return m_bGhostLayerValid ? m_pTexGhostLayer.get() : nullptr; }	//! True when this frame's Execute() actually composited depth of field into the HDR target.	//! CMotionBlurStage needs the fact, not a second guess at it: CDepthOfField::GetParams()	//! advances a temporal smoother on every call, so a second evaluation of the same	//! threshold can disagree with what this stage really did.	bool HasWrittenHDRTarget() const { return m_bWroteHDRTarget; }	//! Field-dependent pupil constant (vDofFieldPupil), derived from the four user values.	//! x = barrel offset at the frame corner per unit of Cat-eye, y = barrel radius - both in	//! PUPIL units (wide-open units divided by the pupil scale, so stopping down shrinks the	//! pupil against a fixed barrel and every field effect fades out by itself); z = coma	//! coefficient, w = astigmatism coefficient. Static and public because the tonemap has to	//! apply the very same light loss the gather and the splat shaped their kernels with:	//! one derivation, three consumers. See FieldPupilSpec.md.	static Vec4 ResolveFieldPupil(float catEye, float pupilScale, float coma, float astigmatism);	//! This frame's wave-optics glare kernel (DiffractionKernelSpec.md). It lives HERE and not in	//! the bloom stage because the pupil does: blades, the polygon exponent, the blade phase, the	//! shape mask and its rotation and scale, and the spherical aberration are all resolved once	//! per frame by Execute() and would otherwise have to travel to the bloom stage as a second	//! set of post params that could drift out of step with the bokeh.	const CDiffractionKernel& GetDiffractionKernel() const { return m_diffraction; }	//! The geometric f-number the pupil was resolved at, i.e. max(N, N_mask) when a mask is	//! bound. The kernel is scale free; this is what turns it into pixels on the sensor.	float GetDiffractionNGeo() const { return m_fDiffractionNGeo; }	//! Full-frame sensor width in mm, as the lens parameters carry it. The kernel's texel pitch	//! is a length ON the sensor, so it needs the sensor's own size to become pixels.	float GetDiffractionSensorWidthMM() const { return m_fDiffractionSensorWidthMM; }private:	Vec4 ToUnitDisk(Vec4& origin, float blades, float shapeExponent, float rotation);	// Splat accumulation layers overlaid on the gathered result: the hybrid highlight splat	// (bSplat, r_DepthOfFieldMode 0) and the internal reflection ghosts (bGhost, amount > 0).	// One pass, because the two draw the SAME object through the same pixel shader - an image	// of the aperture - so every constant describing the pupil is resolved once and shared.	// bLensModel / vLensModel / fSplatCapPx / vGatherFieldPupil2: the lens model	// (DofLensModelSpec.md) resolved once in Execute(). The sprite draws take their own cap and	// the spherical-aberration lane; the overlay pass takes the gather's whole constant, because	// it has to mask the far splats with exactly the sharpness the composite used.	// shapeExponent / edgeSoftness: the iris polygon's shape (0 = circle, 1 = the true polygon)	// and how crisp its edge is cut, both resolved once in Execute() from blade curvature.	void ExecuteSplatLayers(const SDepthOfFieldParams& dofParams, const Vec4& vDofParams0, const Vec4& vDofParams1,	                        float blades, float shapeExponent, float edgeSoftness, bool bSplat, bool bGhost,	                        bool bLensModel, const Vec4& vLensModel, const Vec4& vLensModel2, float fSplatCapPx,	                        const Vec4& vGatherFieldPupil2);	// Mask gather kernel: CDFs importance-sampling the PUPIL (mask x iris disc of radius	// fIrisRadius in mask units, 1 = the mask's bounding circle, >= 1.5 = no clipping), built on	// demand and rebuilt in quantized iris steps. Also resolves the pupil's fill fraction of the	// splat quad for the energy gain.	bool EnsureMaskKernelCDF(const char* szTexName, float fIrisRadius);	bool BuildMaskPupilCDF(float fIrisRadius);	Vec4 SampleMaskKernelTap(float u, float v) const;	float GetMaskPupilFill() const { return m_maskFill; }private:	CStretchRectPass m_passCopySceneTarget;	CFullscreenPass  m_passLayerDownscale;	CFullscreenPass  m_passTileMinCoC[MIN_DOF_COC_K];	CFullscreenPass  m_passGather0;	CFullscreenPass  m_passGather1;	CFullscreenPass  m_passComposition;	// Hybrid highlight splat layer	CPrimitiveRenderPass m_passSpriteSplat;	CRenderPrimitive     m_spriteSplatPrimitive;	CConstantBufferPtr   m_pSpritePerViewCB;	CFullscreenPass      m_passSpriteComposition;	// Internal reflection ghosts (LensGhostSpec.md). Their own primitives and per-view constant	// buffer: the grid is quarter resolution and every ghost layer is a draw of its own, with	// its own place, size and coating colour.	//	// They used to write into the splat layers, which the overlay adds into the HDR target here	// in the DOF stage - and that made every ghost a light source for the glare family, which	// thresholds that target afterwards: ghost chains grew their own horizontal flares and	// stars. A ghost is already a second-order reflection, so a flare off one is third order	// (~1/50 of the ghost) and does not exist. They therefore accumulate into a layer of their	// own, which ExecuteGhostComposite() adds to the frame after the glare sources are out.	static const int     kMaxGhostLayers = 6;	CPrimitiveRenderPass m_passGhostSplat;	CRenderPrimitive     m_ghostPrimitives[kMaxGhostLayers];	CConstantBufferPtr   m_pGhostPerViewCB;	CFullscreenPass      m_passGhostComposition;	// Splat accumulation layers, at FULL resolution. The quad grid stays half resolution (the	// vertex count and the source sampling are unchanged), but the discs are rasterized at	// native resolution so a shape mask keeps its edges instead of being magnified 2x on the	// way back to the HDR target. Allocated lazily, so pure gather (mode 1) pays nothing.	_smart_ptr<CTexture> m_pTexSplatLayerNear;	_smart_ptr<CTexture> m_pTexSplatLayerFar;	int                  m_splatLayerWidth = 0;	int                  m_splatLayerHeight = 0;	bool AcquireSplatLayers(int width, int height);	void ReleaseSplatLayers();	// The ghost accumulation layer, same size and format as the splat layers but allocated only	// on the frames ghosts are actually drawn (Amount 0 costs nothing, and the far more common	// splat-only path does not pay for it either).	_smart_ptr<CTexture> m_pTexGhostLayer;	int                  m_ghostLayerWidth = 0;	int                  m_ghostLayerHeight = 0;	bool                 m_bGhostLayerValid = false; //!< ghosts were drawn this frame, not yet composited	bool AcquireGhostLayer(int width, int height);	void ReleaseGhostLayer();	// Mask-domain gather kernel state. Built once per texture name from the DDS file itself	// (the GPU resource has no CPU-side copy); steady state costs one string compare.	std::vector<float> m_maskRowCDF;    // marginal CDF over rows	std::vector<float> m_maskColCDF;    // conditional CDF per row, row-major	std::vector<uint8> m_maskPixels;    // R channel of the mask, kept so the pupil rebuilds per iris step	int                m_maskCDFWidth = 0;	int                m_maskCDFHeight = 0;	bool               m_maskCDFValid = false;	bool               m_maskPixelsValid = false;	float              m_maskCDFIrisRadius = -1.0f; // quantized iris radius the CDF was built for	float              m_maskBound = 1.0f;          // pupil bounding radius in mask units (min(iris, 1))	float              m_maskFill = 1.0f;           // pupil fill fraction of the splat quad	float              m_maskRotation = 0.0f;       // mask rotation in radians, applied to the gather taps	std::string        m_maskCDFTexName;	// Wave-optics glare kernel and the two per-frame scalars that scale it onto the sensor.	// Resolution independent (the kernel is in pupil units), so it survives a Resize untouched;	// its own destructor waits for any job in flight before the buffers go.	CDiffractionKernel m_diffraction;	float              m_fDiffractionNGeo = 8.0f;	float              m_fDiffractionSensorWidthMM = 36.0f;	bool m_bWroteHDRTarget = false;};